using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace PowerShapeBridge {
 internal static class OwnedTranslationTests {
  static Dictionary<string,object> Clone(Dictionary<string,object> d){return Program.Json.Deserialize<Dictionary<string,object>>(Program.Json.Serialize(d));}
  sealed class Fake : OwnedTranslation.IContext {
   internal Dictionary<string,object> Snapshot,Listing;internal double[] Box={-10,10,-10,10,0,20};internal int Calls,Reads,Code=1;internal bool Throw,WrongCog,Changed;internal Action<int> DuringRead;
   public Dictionary<string,object> Windows(){return Clone(Listing);}
   public Dictionary<string,object> Observation(){Reads++;if(DuringRead!=null)DuringRead(Reads);return Clone(Snapshot);}
   public void ConfirmDocument(){if(Changed)throw new InvalidOperationException("Synthetic active document changed.");}
   public int Composite(int type,int id){ConfirmDocument();if(type!=40||id!=5)throw new InvalidOperationException("Unexpected fake entity.");return 101;}
   public double[] Bounds(int composite){ConfirmDocument();if(composite!=101)throw new InvalidOperationException("Wrong composite.");return Box.ToArray();}
   public int Translate(int composite,double[] vector){ConfirmDocument();Calls++;if(Throw)throw new IOException("Synthetic interrupted COM command.");if(Code==1){Box=Box.Select((x,i)=>x+vector[i/2]).ToArray();var solid=EntitySets.Inventory(Snapshot).Single(e=>Equals(e["nativeTypeCode"],40));var geometry=(Dictionary<string,object>)solid["geometry"];geometry["cogRaw"]=((IList)geometry["cogRaw"]).Cast<object>().Select((x,i)=>Program.StrictDouble(x)+(WrongCog?0:vector[i])).ToArray();}return Code;}
   public void Dispose(){}
  }
  static Fake Context(OwnedOperationPlanTests.Fixture fixture){return new Fake{Snapshot=Clone(fixture.Snapshot),Listing=Clone(fixture.Listing)};}
  static Dictionary<string,object> Handle(OwnedOperationPlanTests.Fixture fixture){var result=fixture.Prepare();if(!Equals(result["state"],"owned_operation_prepared_observed"))throw new Exception("Synthetic packet failed.");return new Dictionary<string,object>{{"ownedOperationId",result["ownedOperationId"]},{"ownedOperationSha256",result["ownedOperationSha256"]}};}
  static Dictionary<string,object> Proof(OwnedOperationPlanTests.Fixture f,Dictionary<string,object> execution,Fake context) {
   string id=(string)execution["operationId"];string receiptPath=Path.Combine(f.Root,"responses",id+".json");string receiptSha=File.Exists(receiptPath)?Program.Hash(receiptPath):NativeJournal.Freeze(receiptPath,execution);var fresh=Clone(context.Snapshot);fresh["timestampUtc"]=DateTime.UtcNow.AddMilliseconds(1).ToString("o");string inspection=Guid.NewGuid().ToString("N");fresh["bridgeRequestId"]=inspection;string inspectionSha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",inspection+".json"),fresh);var listing=Clone(context.Listing);listing["timestampUtc"]=fresh["timestampUtc"];listing["state"]="documents_listed_verified";string listingId=Guid.NewGuid().ToString("N"),listingSha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",listingId+".json"),listing);
   return new Dictionary<string,object>{{"executionRequestId",id},{"executionReceiptSha256",receiptSha},{"inspectionRequestId",inspection},{"inspectionSha256",inspectionSha},{"listingRequestId",listingId},{"listingSha256",listingSha},{"windowNumber",1},{"modelId",9},{"expiresUtc",DateTime.UtcNow.AddSeconds(190).ToString("o")}};
  }
  internal static int Run() {
   int count=0;Action<bool> check=ok=>{if(!ok)throw new Exception("Owned translation test failed at "+count);count++;};
   var f=new OwnedOperationPlanTests.Fixture(true);var args=Handle(f);var context=Context(f);string id=Guid.NewGuid().ToString("N");var result=OwnedTranslation.Execute(f.Root,id,args,context);check(Equals(result["state"],"owned_translation_executed_unverified")&&context.Calls==1&&context.Reads==6&&Equals(result["copyFenced"],true));check(Directory.GetFiles(Path.Combine(f.Root,"operations",id),"*.json").Length==5);string fence=OwnedTranslation.FencePath(f.Root,(string)result["copyId"]);check(File.Exists(fence));var replay=Context(f);check(Equals(OwnedTranslation.Execute(f.Root,Guid.NewGuid().ToString("N"),args,replay)["state"],"owned_translation_rejected_before_change")&&replay.Calls==0);
   var proof=Proof(f,result,context);var verified=OwnedTranslation.Verify(f.Root,proof,context);check(Equals(verified["state"],"owned_translation_verified_observed")&&context.Calls==1&&!File.Exists(fence));check(Directory.GetFiles(Path.Combine(f.Root,"operations",id),"*.json").Length==6);string terminal=Program.Hash(Path.Combine(f.Root,"operations",id,"000005.json"));check(Equals(OwnedTranslation.Verify(f.Root,proof,context)["state"],"owned_translation_verified_observed")&&Program.Hash(Path.Combine(f.Root,"operations",id,"000005.json"))==terminal);var afterReplay=Context(f);check(Equals(OwnedTranslation.Execute(f.Root,Guid.NewGuid().ToString("N"),args,afterReplay)["state"],"owned_translation_rejected_before_change")&&afterReplay.Calls==0);
   foreach(int code in new[]{0,-1}){var other=new OwnedOperationPlanTests.Fixture(true);var h=Handle(other);var fake=Context(other);fake.Code=code;var failure=OwnedTranslation.Execute(other.Root,Guid.NewGuid().ToString("N"),h,fake);check(Equals(failure["state"],"owned_translation_outcome_unknown")&&fake.Calls==1&&Equals(failure["copyFenced"],true));check(Equals(OwnedTranslation.Verify(other.Root,Proof(other,failure,fake),fake)["state"],"owned_translation_verification_rejected")&&fake.Calls==1);var freshPacket=Handle(other);var retry=Context(other);check(Equals(OwnedTranslation.Execute(other.Root,Guid.NewGuid().ToString("N"),freshPacket,retry)["state"],"owned_translation_rejected_before_change")&&retry.Calls==0);}
   var forged=new OwnedOperationPlanTests.Fixture(true);var forgedContext=Context(forged);forgedContext.Code=0;var forgedResult=OwnedTranslation.Execute(forged.Root,Guid.NewGuid().ToString("N"),Handle(forged),forgedContext);forgedResult["returnCode"]=1;forgedContext.Box=forgedContext.Box.Select((v,i)=>v+(i<2?1:0)).ToArray();((Dictionary<string,object>)EntitySets.Inventory(forgedContext.Snapshot).Single(e=>Equals(e["nativeTypeCode"],40))["geometry"])["cogRaw"]=new[]{1,0,10};var forgedVerification=OwnedTranslation.Verify(forged.Root,Proof(forged,forgedResult,forgedContext),forgedContext);check(Equals(forgedVerification["state"],"owned_translation_verification_rejected")&&((string)forgedVerification["error"]).Contains("journal return code")&&File.Exists(OwnedTranslation.FencePath(forged.Root,(string)forgedResult["copyId"])));
   var interrupted=new OwnedOperationPlanTests.Fixture(true);var interruptedContext=Context(interrupted);interruptedContext.Throw=true;var unknown=OwnedTranslation.Execute(interrupted.Root,Guid.NewGuid().ToString("N"),Handle(interrupted),interruptedContext);check(Equals(unknown["state"],"owned_translation_outcome_unknown")&&interruptedContext.Calls==1);check(Equals(OwnedTranslation.Verify(interrupted.Root,Proof(interrupted,unknown,interruptedContext),interruptedContext)["state"],"owned_translation_verification_rejected"));
   var wrong=new OwnedOperationPlanTests.Fixture(true);var wrongContext=Context(wrong);wrongContext.WrongCog=true;var bad=OwnedTranslation.Execute(wrong.Root,Guid.NewGuid().ToString("N"),Handle(wrong),wrongContext);check(Equals(bad["state"],"owned_translation_outcome_unknown")&&wrongContext.Calls==1);var wrongProof=Proof(wrong,bad,wrongContext);check(Equals(OwnedTranslation.Verify(wrong.Root,wrongProof,wrongContext)["state"],"owned_translation_verification_rejected"));var wrongSolid=EntitySets.Inventory(wrongContext.Snapshot).Single(e=>Equals(e["nativeTypeCode"],40));((Dictionary<string,object>)wrongSolid["geometry"])["cogRaw"]=new[]{1,0,10};check(Equals(OwnedTranslation.Verify(wrong.Root,Proof(wrong,bad,wrongContext),wrongContext)["state"],"owned_translation_verified_observed")&&wrongContext.Calls==1);
   var changedDoc=new OwnedOperationPlanTests.Fixture(true);var changedDocContext=Context(changedDoc);changedDocContext.DuringRead=n=>{if(n==4)changedDocContext.Changed=true;};check(Equals(OwnedTranslation.Execute(changedDoc.Root,Guid.NewGuid().ToString("N"),Handle(changedDoc),changedDocContext)["state"],"owned_translation_rejected_before_change")&&changedDocContext.Calls==0);
   var noUnits=new OwnedOperationPlanTests.Fixture();var noUnitsContext=Context(noUnits);check(Equals(OwnedTranslation.Execute(noUnits.Root,Guid.NewGuid().ToString("N"),Handle(noUnits),noUnitsContext)["state"],"owned_translation_rejected_before_change")&&noUnitsContext.Calls==0);
   var intersection=new OwnedOperationPlanTests.Fixture(true);intersection.Intersection(new[]{new[]{40,5}},new[]{new[]{21,8}});var intersectionContext=Context(intersection);check(Equals(OwnedTranslation.Execute(intersection.Root,Guid.NewGuid().ToString("N"),Handle(intersection),intersectionContext)["state"],"owned_translation_rejected_before_change")&&intersectionContext.Calls==0);
   foreach(int phase in new[]{1,3,4}){var changed=new OwnedOperationPlanTests.Fixture(true);var h=Handle(changed);var fake=Context(changed);fake.DuringRead=n=>{if(n==phase)fake.Snapshot["processId"]=2;};var refused=OwnedTranslation.Execute(changed.Root,Guid.NewGuid().ToString("N"),h,fake);check(Equals(refused["state"],"owned_translation_rejected_before_change")&&fake.Calls==0&&!File.Exists(OwnedTranslation.FencePath(changed.Root,changed.BindingId)));if(refused.ContainsKey("copyId"))check(!File.Exists(OwnedTranslation.FencePath(changed.Root,(string)refused["copyId"])));}
   var fenced=new OwnedOperationPlanTests.Fixture(true);var fencedContext=Context(fenced);var fencedResult=OwnedTranslation.Execute(fenced.Root,Guid.NewGuid().ToString("N"),Handle(fenced),fencedContext);var fencedProof=Proof(fenced,fencedResult,fencedContext);string fencedPath=OwnedTranslation.FencePath(fenced.Root,(string)fencedResult["copyId"]);File.AppendAllText(fencedPath," ");check(Equals(OwnedTranslation.Verify(fenced.Root,fencedProof,fencedContext)["state"],"owned_translation_verification_rejected")&&File.Exists(fencedPath));
   foreach(var change in new[]{new Dictionary<string,object>{{"windowNumber",2}},new Dictionary<string,object>{{"executionReceiptSha256",new string('f',64)}},new Dictionary<string,object>{{"expiresUtc",DateTime.UtcNow.AddSeconds(-1).ToString("o")}}}){var invalid=new Dictionary<string,object>(proof);foreach(var pair in change)invalid[pair.Key]=pair.Value;check(Equals(OwnedTranslation.Verify(f.Root,invalid,context)["state"],"owned_translation_verification_rejected"));}
   if(Program.ReadConfig().ownedTranslationsExperimental){foreach(var recipe in new[]{"execute_owned_translation","verify_owned_translation"}){FileRequests.Parse(new string('d',32),Program.Json.Serialize(new{requestId=new string('d',32),operation="recipe.prepare",arguments=new{recipeId=recipe,parameters=recipe=="execute_owned_translation"?args:proof}}));count++;}}
   return count;
  }
 }
}
